BEGIN;
CREATE FUNCTION refs_read_ai_fixed_asset_impairment_posted_reconciliation(p_tenant uuid,p_entity uuid,p_period uuid) RETURNS SETOF jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
  PERFORM refs_assert_scope(p_tenant,p_entity,'AI.ANALYSIS.EXPLAIN');
  RETURN QUERY WITH p AS (SELECT period_id,period_code,starts_on,ends_on FROM accounting_period WHERE tenant_id=p_tenant AND entity_id=p_entity AND period_id=p_period AND ledger_code='PRIMARY'), posted AS (
    SELECT a.fixed_asset_impairment_assessment_evidence_id,
      COALESCE(sum(CASE WHEN j.journal_entry_id IS NOT NULL AND l.account_code=a.impairment_expense_account_code THEN l.debit_amount-l.credit_amount ELSE 0 END),0)::numeric(20,4) expense,
      COALESCE(sum(CASE WHEN j.journal_entry_id IS NOT NULL AND l.account_code=a.accumulated_impairment_account_code THEN l.credit_amount-l.debit_amount ELSE 0 END),0)::numeric(20,4) accumulated,
      array_agg(DISTINCT l.journal_entry_id ORDER BY l.journal_entry_id) FILTER(WHERE j.journal_entry_id IS NOT NULL) je_ids,array_agg(DISTINCT l.journal_line_id ORDER BY l.journal_line_id) FILTER(WHERE j.journal_entry_id IS NOT NULL) jl_ids,array_agg(DISTINCT l.ledger_line_id ORDER BY l.ledger_line_id) FILTER(WHERE j.journal_entry_id IS NOT NULL) ll_ids
    FROM fixed_asset_impairment_assessment_evidence a CROSS JOIN p LEFT JOIN ledger_line l ON l.tenant_id=a.tenant_id AND l.entity_id=a.entity_id AND l.dimensions->>'impairment_assessment_evidence_id'=a.fixed_asset_impairment_assessment_evidence_id::text AND l.account_code IN(a.impairment_expense_account_code,a.accumulated_impairment_account_code) LEFT JOIN journal_entry j ON j.tenant_id=l.tenant_id AND j.entity_id=l.entity_id AND j.journal_entry_id=l.journal_entry_id AND j.status='POSTED' AND j.journal_date BETWEEN p.starts_on AND p.ends_on
    WHERE a.tenant_id=p_tenant AND a.entity_id=p_entity AND a.accounting_period_id=p_period AND a.status='INDEPENDENTLY_REVIEWED' AND a.impairment_loss>0 GROUP BY a.fixed_asset_impairment_assessment_evidence_id
  ) SELECT jsonb_build_object('period_id',a.accounting_period_id,'period_code',p.period_code,'fixed_asset_register_evidence_id',a.fixed_asset_register_evidence_id,'impairment_assessment_evidence_id',a.fixed_asset_impairment_assessment_evidence_id,'impairment_assessment_hash',a.impairment_assessment_hash,'asset_tag',r.asset_tag,'currency',a.currency,'expected_impairment_loss',to_char(a.impairment_loss,'FM999999999999990.0000'),'posted_impairment_expense',to_char(x.expense,'FM999999999999990.0000'),'posted_accumulated_impairment',to_char(x.accumulated,'FM999999999999990.0000'),'expense_variance',to_char(x.expense-a.impairment_loss,'FM999999999999990.0000'),'accumulated_variance',to_char(x.accumulated-a.impairment_loss,'FM999999999999990.0000'),'journal_entry_ids',COALESCE(x.je_ids,ARRAY[]::uuid[]),'journal_line_ids',COALESCE(x.jl_ids,ARRAY[]::uuid[]),'ledger_line_ids',COALESCE(x.ll_ids,ARRAY[]::uuid[]),'lineage_status','ASSESSMENT_ID_BOUND_POSTED') FROM fixed_asset_impairment_assessment_evidence a JOIN fixed_asset_register_evidence r ON r.fixed_asset_register_evidence_id=a.fixed_asset_register_evidence_id JOIN posted x ON x.fixed_asset_impairment_assessment_evidence_id=a.fixed_asset_impairment_assessment_evidence_id CROSS JOIN p ORDER BY r.asset_tag;
END;$$;
REVOKE EXECUTE ON FUNCTION refs_read_ai_fixed_asset_impairment_posted_reconciliation(uuid,uuid,uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION refs_read_ai_fixed_asset_impairment_posted_reconciliation(uuid,uuid,uuid) TO refs_app;
COMMIT;
